def fn(x):
    # QWERTY substitution alphabet
    qwerty = "qwertyuiopasdfghjklzxcvbnm"
    # Build mapping from plain alphabet a‑z to the QWERTY order
    trans = {chr(ord('a') + i): qwerty[i] for i in range(26)}

    res = []
    for ch in x:
        if ch.isalpha():
            low = ch.lower()
            mapped = trans.get(low, low)          # fallback to the same char if not found
            res.append(mapped.upper() if ch.isupper() else mapped)
        else:
            res.append(ch)
    return ''.join(res)

